script.setup:
// lindenmayer rewrites each plant's L-system; the scene walks the result with a turtle
// and grows the branches along their distance from the root, swaying in the wind.
const mod = await ctx.utils.import("https://esm.sh/lindenmayer@1.5.4");
const LSystem = mod.default ?? mod;
const pick = (...options) => ({ successors: options.map((successor) => ({ weight: 1, successor })) });
// Four kinds of plant: [axiom, productions, iterations, angle (degrees)].
const KINDS = [
  ["X", { X: pick("F+[[X]-X]-F[-FX]+X", "F-[[X]+X]+F[+FX]-X"), F: "FF" }, 5, 23],
  ["F", { F: pick("F[+F]F[-F]F", "F[+F]F", "F[-F]F") }, 5, 26],
  ["X", { X: pick("F[+X]F[-X]+X", "F[-X]F[+X]-X", "F[+X][-X]FX"), F: "FF" }, 6, 21],
  ["F", { F: pick("FF-[-F+F+F]+[+F-F-F]", "FF+[+F-F]-[-F+F+F]") }, 3, 20],
];
const gl = ctx.gl;
const makeVao = (layout) => {
  const vao = gl.createVertexArray(), buffer = gl.createBuffer();
  gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  const stride = layout.reduce((a, b) => a + b, 0) * 4;
  let offset = 0;
  layout.forEach((n, i) => { gl.enableVertexAttribArray(i); gl.vertexAttribPointer(i, n, gl.FLOAT, false, stride, offset); offset += n * 4; });
  gl.bindVertexArray(null);
  return { vao, buffer, count: 0 };
};
const SWAY = `
uniform float u_time; uniform float u_wind; uniform float u_aspect;
vec2 sway(vec2 p, float plant, float base) {
  float hgt = max(p.y - 0.1, 0.0);
  p.x += u_wind * 0.05 * hgt * hgt * (sin(u_time * 1.3 + plant * 1.7 + p.y * 2.5) + 0.45 * sin(u_time * 2.9 + plant));
  return p;
}
vec4 toClip(vec2 p) { return vec4(p.x / u_aspect * 2.0 - 1.0, p.y * 2.0 - 1.0, 0.0, 1.0); }`;
const stems = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec4 a_ends; layout(location=1) in vec4 a_info; layout(location=2) in vec2 a_corner;
uniform float u_grow; out float v_shade; out float v_depth;` + SWAY + `
void main(){
  float t = clamp((u_grow - a_info.x) / max(a_info.y - a_info.x, 1e-4), 0.0, 1.0);
  vec2 a = sway(a_ends.xy, a_info.w, 0.0), b = sway(mix(a_ends.xy, a_ends.zw, t), a_info.w, 0.0);
  vec2 dir = normalize(b - a + vec2(0.0, 1e-6)), nrm = vec2(-dir.y, dir.x);
  float width = a_info.z * (t > 0.0 ? 1.0 : 0.0) * mix(1.0, 0.75, a_corner.x);
  vec2 p = mix(a, b, a_corner.x) + nrm * a_corner.y * width * 0.5 + dir * (a_corner.x * 2.0 - 1.0) * width * 0.3;
  v_shade = a_corner.y; v_depth = a_info.x;
  gl_Position = toClip(p);
}`, `#version 300 es
precision highp float; in float v_shade; in float v_depth; out vec4 outColor; uniform vec3 u_stem;
void main(){
  vec3 c = mix(u_stem * 0.55, u_stem * 1.25 + vec3(0.05, 0.12, 0.02), smoothstep(0.1, 0.9, v_depth));
  outColor = vec4(c * (0.75 + 0.35 * v_shade), 1.0);
}`);
const leaves = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_pos; layout(location=1) in vec2 a_info;
uniform float u_grow; uniform float u_px; out float v_hue; out float v_open;` + SWAY + `
void main(){
  v_open = clamp((u_grow - a_info.x) * 8.0, 0.0, 1.0);
  v_hue = a_info.y;
  gl_Position = toClip(sway(a_pos, floor(a_info.y), 0.0));
  gl_PointSize = u_px * v_open * (0.75 + 0.5 * fract(a_info.y * 7.31 + a_pos.x * 13.0));
}`, `#version 300 es
precision highp float; in float v_hue; in float v_open; out vec4 outColor; uniform vec3 u_bloom[4];
void main(){
  vec2 p = gl_PointCoord - 0.5;
  // Five petals.
  float ang = atan(p.y, p.x), r = length(p) * 2.0;
  float petal = 0.62 + 0.38 * cos(ang * 5.0);
  if (r > petal || v_open <= 0.0) discard;
  vec3 c = u_bloom[int(floor(v_hue)) % 4];
  c = mix(vec3(1.0, 0.92, 0.6), c, smoothstep(0.12, 0.3, r));
  outColor = vec4(c * (1.05 - 0.35 * r), 1.0);
}`);
const sky = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor; uniform vec2 u_resolution; uniform float u_ground;
void main(){
  vec3 top = vec3(0.05, 0.06, 0.12), horizon = vec3(0.32, 0.22, 0.3);
  vec3 c = mix(horizon, top, pow(v_uv.y, 0.7));
  vec2 sun = vec2(0.72, 0.55); float aspect = u_resolution.x / u_resolution.y;
  float d = length((v_uv - sun) * vec2(aspect, 1.0));
  c += vec3(1.0, 0.6, 0.35) * (0.5 * exp(-d * 6.0) + smoothstep(0.075, 0.07, d) * 0.6);
  if (v_uv.y < u_ground) c = mix(vec3(0.08, 0.06, 0.06), vec3(0.14, 0.1, 0.09), v_uv.y / u_ground);
  outColor = vec4(c, 1.0);
}`);
Object.assign(ctx.state, { LSystem, KINDS, stems, leaves, sky, stemVao: makeVao([4, 4, 2]), leafVao: makeVao([2, 2]), grow: 0, key: "", hold: 0 });

// Build the whole garden: one L-system per plant, a turtle walk, quads for the branches.
ctx.state.build = (detail, angleShift, aspect) => {
  const s = ctx.state, ground = 0.12, plants = 5;
  const segData = [], leafData = [];
  for (let p = 0; p < plants; p++) {
    const kind = s.KINDS[(p + s.seed) % s.KINDS.length];
    const lsys = new s.LSystem({ axiom: kind[0], productions: kind[1] });
    const text = lsys.iterate(Math.max(1, kind[2] + detail));
    const turn = (kind[3] + angleShift) * Math.PI / 180;
    // Turtle walk in local units; remember the distance from the root of every point.
    let x = 0, y = 0, a = Math.PI / 2 + (Math.random() - 0.5) * 0.15, d = 0, depth = 0;
    const stack = [], segs = [], tips = [];
    for (const ch of text) {
      if (ch === "F") {
        const nx = x + Math.cos(a), ny = y + Math.sin(a);
        segs.push([x, y, nx, ny, d, d + 1, depth]);
        x = nx; y = ny; d += 1;
      } else if (ch === "+") a += turn * (0.85 + Math.random() * 0.3);
      else if (ch === "-") a -= turn * (0.85 + Math.random() * 0.3);
      else if (ch === "[") { stack.push([x, y, a, d, depth]); depth++; }
      else if (ch === "]") { tips.push([x, y, d]); [x, y, a, d, depth] = stack.pop(); }
    }
    tips.push([x, y, d]);
    let x0 = Infinity, x1 = -Infinity, y1 = 0, dmax = 1;
    for (const g of segs) { x0 = Math.min(x0, g[0], g[2]); x1 = Math.max(x1, g[0], g[2]); y1 = Math.max(y1, g[1], g[3]); dmax = Math.max(dmax, g[5]); }
    // Fit every plant to its slot along the ground, at varied heights.
    const slot = aspect / plants, height = 0.45 + 0.35 * Math.random();
    const k = Math.min(height / y1, slot * 1.25 / Math.max(x1 - x0, 1e-3));
    const cx = slot * (p + 0.5) + (Math.random() - 0.5) * slot * 0.2, mid = (x0 + x1) / 2;
    const T = (px, py) => [cx + (px - mid) * k, ground + py * k];
    for (const [ax, ay, bx, by, da, db, dep] of segs) {
      const [Ax, Ay] = T(ax, ay), [Bx, By] = T(bx, by);
      const width = Math.max(0.0016, 0.011 * Math.pow(0.7, dep) * (1 - 0.6 * da / dmax));
      for (const [along, side] of [[0, -1], [1, -1], [1, 1], [0, -1], [1, 1], [0, 1]]) {
        segData.push(Ax, Ay, Bx, By, da / dmax, db / dmax, width, p, along, side);
      }
    }
    for (const [tx, ty, td] of tips) { if (td > 0 && Math.random() < 0.6) { const [X, Y] = T(tx, ty); leafData.push(X, Y, td / dmax + 0.05, p + Math.random() * 0.99); } }
  }
  for (const [vao, data, n] of [[s.stemVao, segData, 10], [s.leafVao, leafData, 4]]) {
    gl.bindBuffer(gl.ARRAY_BUFFER, vao.buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(data), gl.STATIC_DRAW);
    vao.count = data.length / n;
  }
  s.grow = 0; s.hold = 0;
};
ctx.state.seed = Math.floor(Math.random() * 4);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution, aspect = w / h;
const key = [u.u_detail, u.u_angle, aspect.toFixed(3)].join();
if (key !== s.key || u.u_regrow) { s.key = key; if (u.u_regrow) s.seed++; s.build(u.u_detail, u.u_angle, aspect); }
// Grow; when the garden has bloomed, wait a while and plant a new one.
if (s.grow < 1.15) s.grow += ctx.dt * u.u_speed / 6;
else if ((s.hold += ctx.dt) > 8) { s.seed++; s.build(u.u_detail, u.u_angle, aspect); }
gl.useProgram(s.sky);
ctx.utils.drawFullscreen(s.sky, { u_ground: 0.12 });
const common = { u_time: ctx.time, u_wind: u.u_wind, u_aspect: aspect, u_grow: s.grow };
gl.useProgram(s.stems);
ctx.utils.setUniforms(s.stems, { ...common, u_stem: u.u_stem });
gl.bindVertexArray(s.stemVao.vao);
gl.drawArrays(gl.TRIANGLES, 0, s.stemVao.count);
gl.useProgram(s.leaves);
ctx.utils.setUniforms(s.leaves, { ...common, u_px: h * 0.016, u_bloom: [u.u_bloom1, u.u_bloom2, [1.0, 0.85, 0.35], [0.75, 0.6, 1.0], ].flat() });
gl.bindVertexArray(s.leafVao.vao);
gl.drawArrays(gl.POINTS, 0, s.leafVao.count);
gl.bindVertexArray(null);
ctx.publish("branches", s.stemVao.count / 6);
ctx.publish("growth", Math.min(1, s.grow).toFixed(2));
